@pytest.mark.parametrize('spacing', [[0], {'spacing': 1}, 'invalid'])
@pytest.mark.parametrize('setter', [False, True])
def test_invalid_linespacing(spacing, setter):
    text = Text()
    with pytest.raises(TypeError, match="spacing.*must be an instance"):
        if setter:
            text.set_linespacing(spacing)
        else:
            plt.figtext(.5, .5, 'foo', linespacing=spacing)


@pytest.mark.parametrize('value', [False, True, 0, 1, [], [0], np.bool_(True)])
@pytest.mark.parametrize('setter', [False, True])
def test_transform_rotates_text_bool(value, setter):
    fig = plt.figure()
    transform = mtransforms.Affine2D().rotate_deg(30)
    kwargs = {} if setter else {'transform_rotates_text': value}
    text = fig.text(.5, .5, 'foo', transform=transform, **kwargs)
    if setter:
        text.set_transform_rotates_text(value)
    assert text.get_transform_rotates_text() is bool(value)
    assert_almost_equal(text.get_rotation(), 30 if value else 0)
    fig.canvas.draw()


